    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');
    const key = decodeComponent(eqIndex === -1 ? pair : pair.slice(0, eqIndex));
    if (key === '') continue;

    const value = eqIndex === -1 ? '' : decodeComponent(pair.slice(eqIndex + 1));

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}

