  const replaced = str.replace(/\+/g, ' ');

  const hexToByte = (code) => {
    if (code < '0' || code > '9') return -1;
    return code.charCodeAt(0) - 48;
  };

  let out = '';
  let i = 0;
  while (i < replaced.length) {
    const c = replaced[i];
    if (c !== '%') {
      out += c;
      i++;
      continue;
    }

