    const lo = hexToByte(replaced[i + 2]);
    if (hi < 0 || lo < 0) {
      throw new URIError('Malformed percent encoding');
    }

    const byte = (hi << 4) + lo;
    out += String.fromCharCode(byte);
    i += 3;
  }

  try {
    return decodeURIComponent(out);
  } catch (err) {
    throw new URIError('Malformed percent encoding');
  }
}

