function topoSort(graph) {
  const deps = {};
  const indegree = {};

  const addTask = (name) => {
    if (!(name in deps)) {
      deps[name] = new Set();
      indegree[name] = 0;
    }
  };

  const addDep = (task, dep) => {
    if (!deps[task].has(dep)) {
      deps[task].add(dep);
      indegree[task]++;
    }
  };

  for (const name of Object.keys(graph)) {
    addTask(name);
  }
  for (const [task, list] of Object.entries(graph)) {
    for (const dep of list) addDep(task, dep);
  }

  const ready = [];
  for (const name of Object.keys(deps)) {
    if (indegree[name] === 0) ready.push(name);
  }
  ready.sort();

  const result = [];
  const placed = new Set();
  let placedCount = 0;

  while (ready.length > 0) {
    const name = ready.shift();
    result.push(name);
    placed.add(name);
    placedCount++;
    for (const dep of Object.keys(deps)) {
      if (deps[dep].has(name) && !placed.has(dep)) {
        indegree[dep]--;
        if (indegree[dep] === 0) {
          ready.push(dep);
          ready.sort();
        }
      }
    }
  }

  if (placedCount !== Object.keys(deps).length) {
    throw new Error('cycle detected');
  }

  return result;
}

module.exports = { topoSort };
