import re

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")

    if not text:
        raise ValueError("duration cannot be empty")

    pattern = re.compile(r'(\d+)([dhms])')
    matches = pattern.findall(text)

    if not matches:
        raise ValueError("invalid duration format")

    total = 0
    last_index = -1

    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    for number, unit in matches:
        unit_index = list(unit_values.keys()).index(unit)
        if unit_index <= last_index:
            raise ValueError("units must be in strictly descending order")
        last_index = unit_index
        total += int(number) * unit_values[unit]

    reconstructed = ''.join(n + u for n, u in matches)
    if reconstructed != text:
        raise ValueError("invalid duration format")

    return total
