function isValidCardNumber(input) {
  if (typeof input !== 'string') return false;
  const s = input.replace(/[\s-]/g, '');
  if (!/^\d+$/.test(s)) return false;
  const n = s.length;
  if (n < 12 || n > 19) return false;
  let sum = 0;
  for (let i = n - 1; i >= 0; i--) {
    let d = Number(s[i]);
    if ((n - 1 - i) % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

