def business_days(start, end, holidays=()):
    def parse(d):
        try:
            return datetime.strptime(d, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError("invalid date string")
    s, e = parse(start), parse(end)
    if e < s:
        raise ValueError("end is earlier than start")
    hols = set()
    for h in holidays:
        hd = parse(h)
        if s <= hd < e and hd.weekday() < 5:
            hols.add(hd)
    count = 0
    d = s
    while d < e:
        if d.weekday() < 5 and d not in hols:
            count += 1
        d += timedelta(days=1)
    return count
