  const isUpper = (ch) => /[A-Z]/.test(ch);
  const isDigit = (ch) => /[0-9]/.test(ch);

  let out = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    out += ch;

    if (!isUpper(ch) || i === str.length - 1) {
      continue;
    }

    const next = str[i + 1];
    const nextNext = i + 2 < str.length ? str[i + 2] : '';

    // Rule (2): end of an acronym (upper followed by upper then lower)
    if (isUpper(next) && isLower(nextNext)) {
      out += '_';
    } else if (i + 1 < str.length && isLower(next) && isUpper(nextNext)) {
      // Rule (2) variant: acronym ending before a new PascalCase word
      // e.g. "HTTPResponse" -> "http_response"
      out += '_';
    } else if (isLower(next) || isDigit(next)) {
      // Rule (1): lower/digit followed by upper
      out += '_';
    }
  }

  return out.toLowerCase();
}

