function topoSort(graph) {
  const names = new Set();
  for (const key of Object.keys(graph)) {
    names.add(key);
    for (const dep of graph[key]) {
      names.add(dep);
    }
  }

  const deps = {};
  for (const name of names) {
    const list = Object.prototype.hasOwnProperty.call(graph, name) ? graph[name] : [];
    const uniq = [...new Set(list)];
    for (const dep of uniq) {
      if (!names.has(dep)) throw new Error('unknown dependency');
    }
    deps[name] = uniq;
  }

  const result = [];
  const placed = new Set();
  while (result.length < names.size) {
    const ready = [];
    for (const name of names) {
      if (placed.has(name)) continue;
      if (deps[name].every((dep) => placed.has(dep))) ready.push(name);
    }
    if (ready.length === 0) throw new Error('cycle in dependencies');
    ready.sort();
    const pick = ready[0];
    placed.add(pick);
    result.push(pick);
  }
  return result;
}

module.exports = { topoSort };
