function decodeURIComponentStrict(s) {
  let out = '';
  let i = 0;
  const n = s.length;
  while (i < n) {
    const c = s[i];
    if (c === '+') {
      out += ' ';
      i += 1;
    } else if (c === '%') {
      if (i + 3 > n) throw new URIError('malformed percent encoding');
      const hi = parseInt(s.slice(i + 1, i + 3), 16);
      const lo = parseInt(s.slice(i + 3, i + 5), 16);
      if (Number.isNaN(hi) || Number.isNaN(lo)) throw new URIError('malformed percent encoding');
      out += String.fromCharCode(hi * 16 + lo);
      i += 3;
    } else {
      out += c;
      i += 1;
    }
  }
  return out;
}

