  const deps = {};
  const tasks = new Set();
  for (const name in graph) {
    tasks.add(name);
    const list = graph[name];
    if (list) {
      for (const dep of list) {
        tasks.add(dep);
        if (!deps[name]) deps[name] = new Set();
        deps[name].add(dep);
      }
    }
  }

  const remaining = new Set(tasks);
  const result = [];

  while (remaining.size > 0) {
    const ready = [];
    for (const task of remaining) {
      const d = deps[task];
      if (!d || d.size === 0) ready.push(task);
    }
    if (ready.length === 0) throw new Error('cycle detected');
    ready.sort();
    const pick = ready[0];
    result.push(pick);
    remaining.delete(pick);
    for (const other of remaining) {
      if (deps[other] && deps[other].has(pick)) deps[other].delete(pick);
    }
  }

  return result;
}

