  let remaining = tasks.size;

  while (remaining > 0) {
    let candidate = null;
    for (const t of tasks) {
      if (placed.has(t)) continue;
      const ok = deps.get(t).every(d => placed.has(d));
      if (!ok) continue;
      if (candidate === null || t < candidate) candidate = t;
    }
    if (candidate === null) throw new Error('cycle');
    result.push(candidate);
    placed.add(candidate);
    remaining--;
  }

  return result;
}

