function topoSort(graph) {
  const deps = Object.create(null);
  const tasks = new Set();

  for (const name of Object.keys(graph)) {
    tasks.add(name);
    const unique = new Set();
    for (const dep of graph[name]) {
      tasks.add(dep);
      unique.add(dep);
    }
    deps[name] = Array.from(unique);
  }
  for (const task of tasks) {
    if (!(task in deps)) deps[task] = [];
  }

  const placed = new Set();
  const result = [];
  const total = tasks.size;

  while (result.length < total) {
    let chosen = null;
    for (const task of tasks) {
      if (placed.has(task)) continue;
      const ready = deps[task].every((dep) => placed.has(dep));
      if (!ready) continue;
      if (chosen === null || task < chosen) chosen = task;
    }
    if (chosen === null) {
      throw new Error('cycle detected in dependencies');
    }
    placed.add(chosen);
    result.push(chosen);
