  const isUpper = (ch) => /[A-Z]/.test(ch);
  const isLower = (ch) => /[a-z]/.test(ch);

  let result = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (isUpper(ch)) {
      const prev = str[i - 1];
      const next = str[i + 1];
      const prevIsLowerOrDigit = prev !== undefined && /[a-z0-9]/.test(prev);
      const nextIsLower = next !== undefined && isLower(next);

      if (prevIsLowerOrDigit || nextIsLower) {
        result += '_';
      }
      result += ch;
    } else {
      result += ch;
    }
  }

  return result.toLowerCase();
}

