function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const set = new Set();

  if (spec.trim() === '') {
    return [];
  }

  const parts = spec.split(',');
  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part in spec');
    }

    const isRange = trimmed.includes('-');
    if (isRange) {
      const dashCount = (trimmed.match(/-/g) || []).length;
      if (dashCount !== 1) {
        throw new SyntaxError('Invalid range: ' + trimmed);
      }
      const [lo, hi] = trimmed.split('-');
      const loNum = Number(lo);
      const hiNum = Number(hi);
      if (!/^\d+$/.test(lo) || !/^\d+$/.test(hi)) {
        throw new SyntaxError('Invalid range: ' + trimmed);
      }
      if (loNum > hiNum) {
        throw new RangeError('Range start greater than end: ' + trimmed);
      }
      for (let i = loNum; i <= hiNum; i++) {
        set.add(i);
      }
    } else {
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('Invalid number: ' + trimmed);
      }
      set.add(Number(trimmed));
    }
  }

  return Array.from(set).sort((a, b) => a - b);
}

