  let value = n;
  let unitIndex = 0;

  while (unitIndex < units.length - 1 && value >= 1024) {
    value /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  const rounded = Math.round(value * 10) / 10;

  // If rounding causes 1024, move up one unit
  if (rounded >= 1024 && unitIndex < units.length - 1) {
    rounded /= 1024;
    unitIndex++;
  }

  const str = Number.isInteger(rounded) ? String(rounded) : String(rounded);
  return `${str} ${units[unitIndex]}`;
}

