      throw new SyntaxError('empty part');
    }

    const dashCount = trimmed.split('-').length - 1;

    if (dashCount === 1) {
      const [loStr, hiStr] = trimmed.split('-');

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
