      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('range start is greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        set.add(i);
      }
    } else if (dashCount === 0) {
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('invalid integer part');
      }
      set.add(parseInt(trimmed, 10));
    } else {
      throw new SyntaxError('too many dashes');
    }
  }

  return [...set].sort((a, b) => a - b);
}

