    matches = list(pattern.finditer(s))
    pos = 0
    for m in matches:
        if m.start() != pos:
            raise ValueError("invalid format")
        pos = m.end()
    if pos != len(s):
        raise ValueError("trailing digits with no character")
    out = []
    for m in matches:
        count = int(m.group(1))
        if count == 0:
            raise ValueError("count must be at least 1")
        out.append(m.group(2) * count)
