    i, n = 0, len(s)
    while i < n:
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("missing count")
        count = int(s[i:j])
        if count == 0:
            raise ValueError("count must be at least 1")
        if j >= n:
            raise ValueError("trailing digits with no character")
        out.append(s[j] * count)
        i = j + 1
    return "".join(out)
