      throw new SyntaxError('empty part');
    }

    const dashCount = (token.match(/-/g) || []).length;
    if (dashCount > 1) {
      throw new SyntaxError('more than one dash');
    }

    if (dashCount === 1) {
      const [lo, hi] = token.split('-');

      if (!/^\d+$/.test(lo) || !/^\d+$/.test(hi)) {
        throw new SyntaxError('malformed range');
      }

      const start = parseInt(lo, 10);
      const end = parseInt(hi, 10);

      if (start > end) {
        throw new RangeError('range start greater than end');
      }

      for (let i = start; i <= end; i++) {
        values.add(i);
      }
    } else {
      if (!/^\d+$/.test(token)) {
        throw new SyntaxError('malformed part');
      }
      values.add(parseInt(token, 10));
    }
  }

  return Array.from(values).sort((a, b) => a - b);
}

