import re


def _check_str(s):
    if not isinstance(s, str):
        raise TypeError("input must be a string")


def rle_encode(s):
    _check_str(s)
    if any(ch.isdigit() for ch in s):
        raise ValueError("input must not contain digit characters")
    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        out.append(str(j - i) + s[i])
        i = j
    return "".join(out)


def rle_decode(s):
    _check_str(s)
    if s == "":
        return ""
    pattern = re.compile(r"(0|[1-9]\d*)")
    out = []
    i = 0
    n = len(s)
    while i < n:
        m = pattern.match(s, i)
        if m is None:
            raise ValueError("invalid encoding")
        count = int(m.group(1))
        i = m.end()
        if i >= n:
            raise ValueError("trailing digits with no character")
        ch = s[i]
        if ch.isdigit():
            raise ValueError("missing character after count")
        out.append(ch * count)
        i += 1
    return "".join(out)
