const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }
  if (!DATE_RE.test(dateStr)) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  const year = Number(dateStr.slice(0, 4));
  const month = Number(dateStr.slice(5, 7));
  const day = Number(dateStr.slice(8, 10));

  if (year < 1 || year > 9999) {
    throw new RangeError('year must be between 0001 and 9999');
  }

  const monthLengths = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  if (month < 1 || month > 12) {
    throw new RangeError('month must be between 01 and 12');
  }
  const dim = month === 2 && isLeap ? 29 : monthLengths[month - 1];
  if (day < 1 || day > dim) {
    throw new RangeError('day is invalid for the given month');
  }

  let resultYear = year;
  let resultMonth = month;
  let resultDay = day;
  let remaining = days;

  if (remaining > 0) {
    while (remaining > 0) {
      const nextDim = resultMonth === 2 && isLeap(resultYear) ? 29 : monthLengths[resultMonth - 1];
      if (resultDay + remaining <= nextDim) {
        resultDay += remaining;
        remaining = 0;
      } else {
        remaining -= nextDim - resultDay + 1;
        resultDay = 1;
        resultMonth += 1;
        if (resultMonth > 12) {
          resultMonth = 1;
          resultYear += 1;
        }
      }
    }
  } else if (remaining < 0) {
    remaining = -remaining;
    while (remaining > 0) {
      if (resultDay - remaining >= 1) {
        resultDay -= remaining;
        remaining = 0;
      } else {
        remaining -= resultDay - 1;
        resultDay = 1;
        resultMonth -= 1;
        if (resultMonth < 1) {
          resultMonth = 12;
          resultYear -= 1;
        }
        resultDay = monthLengths[resultMonth - 1] === 29 && isLeap(resultYear)
          ? 29
          : monthLengths[resultMonth - 1];
      }
    }
  }

  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('year must be between 0001 and 9999');
  }

  const pad = (n) => String(n).padStart(2, '0');
