    throw new RangeError('year out of range');
  }

  const monthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeap = (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0));
  const monthLen = monthLengths[month - 1] + (month === 2 && isLeap ? 1 : 0);

  if (month < 1 || month > 12 || day < 1 || day > monthLen) {
    throw new RangeError('invalid calendar date');
  }

  const msPerDay = 86400000;
  const utc = Date.UTC(year, month - 1, day);
  const target = utc + days * msPerDay;
  const result = new Date(target);

  const ry = result.getUTCFullYear();
  if (ry < 1 || ry > 9999) {
    throw new RangeError('result year out of range');
  }

  const rm = String(result.getUTCMonth() + 1).padStart(2, '0');
  const rd = String(result.getUTCDate()).padStart(2, '0');
  const ryear = String(ry).padStart(4, '0');
  return `${ryear}-${rm}-${rd}`;
}

