function ageOn(birth, on) {
  const parse = (s) => {
    if (typeof s !== "string") throw new RangeError("invalid date");
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
    if (!m) throw new RangeError("invalid date");
    const y = +m[1], mo = +m[2], d = +m[3];
    const daysInMonth = new Date(y, mo, 0).getDate();
    if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth) throw new RangeError("invalid date");
    return { y, mo, d };
  };

  const b = parse(birth);
  const o = parse(on);

  if (o.y < b.y || (o.y === b.y && (o.mo < b.mo || (o.mo === b.mo && o.d < b.d)))) {
    throw new RangeError("on is earlier than birth");
  }

  const leap = (y) => (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0));

  let age = o.y - b.y;
  if (o.mo < b.mo || (o.mo === b.mo && o.d < b.d)) age--;

  if (b.mo === 2 && b.d === 29 && !leap(o.y)) {
    const bd = new Date(o.y, 1, 1); // Feb 1 of `on` year
    const bd29 = new Date(o.y, 1, 29); // Feb 29; invalid in non-leap year, rolls to Mar 1
    const bd31 = new Date(o.y, 2, 1); // Mar 1
    const cmp = (a, b2) => (a < b2 ? -1 : a > b2 ? 1 : 0);
    const birthday = new Date(o.y, 2, 1); // Feb 29 -> Mar 1 in non-leap year
    const onDate = new Date(o.y, o.mo - 1, o.d);
    if (cmp(onDate, birthday) < 0) age--;
  }

  return age;
}

