function retry(fn, attempts) {
  return new Promise((resolve, reject) => {
    if (typeof fn !== "function") {
      reject(new TypeError("fn must be a function"));
      return;
    }
    if (
      typeof attempts !== "number" ||
      !Number.isInteger(attempts) ||
      attempts < 1
    ) {
      reject(new RangeError("attempts must be an integer >= 1"));
      return;
    }

    let attemptNumber = 0;

    function nextAttempt() {
      attemptNumber += 1;
      try {
        const result = fn(attemptNumber);
        Promise.resolve(result).then(
          (value) => resolve(value),
          (err) => {
            if (attemptNumber < attempts) {
              nextAttempt();
            } else {
              reject(err);
            }
          }
        );
      } catch (err) {
        if (attemptNumber < attempts) {
          nextAttempt();
        } else {
          reject(err);
        }
      }
    }

    nextAttempt();
  });
}

module.exports = { retry };
