def maze_steps(grid):
    if not grid:
        raise ValueError("grid must not be empty")

    rows = len(grid)
    cols = len(grid[0])

    start = exit_pos = None
    for r, row in enumerate(grid):
        if len(row) != cols:
            raise ValueError("rows must all be the same length")
        for c, ch in enumerate(row):
            if ch not in "SE#.\n":
                raise ValueError("invalid character")
            if ch == "S":
                if start is not None:
                    raise ValueError("exactly one S required")
                start = (r, c)
            elif ch == "E":
                if exit_pos is not None:
                    raise ValueError("exactly one E required")
                exit_pos = (r, c)

    if start is None or exit_pos is None:
        raise ValueError("exactly one S and exactly one E required")

    if (start[0], start[1]) == (exit_pos[0], exit_pos[1]):
        return 0

    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        d = dist[(r, c)]
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in dist:
                ch = grid[nr][nc]
                if ch in "SE.":
                    dist[(nr, nc)] = d + 1
                    if (nr, nc) == exit_pos:
                        return d + 1
                    queue.append((nr, nc))
    return -1
