function parseDate(str) {
  if (typeof str !== 'string') {
    throw new RangeError('date must be a string');
  }
  const m = str.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) {
    throw new RangeError('invalid date format: ' + str);
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    throw new RangeError('invalid date: ' + str);
  }
  if (!isValidDate(year, month, day)) {
    throw new RangeError('invalid date: ' + str);
  }
  return { year, month, day };
}

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function dateValue(y, m, d) {
  return y * 10000 + m * 100 + d;
}

function ageOn(birth, on) {
  const b = parseDate(birth);
  const o = parseDate(on);

  if (dateValue(o.year, o.month, o.day) < dateValue(b.year, b.month, b.day)) {
    throw new RangeError('"on" must not be earlier than "birth"');
  }

  const month = b.month === 2 && b.day === 29 ? 3 : b.month;
  const day = b.month === 2 && b.day === 29 ? 1 : b.day;

  const bd = new Date(Date.UTC(b.year, month - 1, day));
  const od = new Date(Date.UTC(o.year, o.month, o.day));
  const age = Math.floor((od - bd) / (365.25 * 24 * 3600 * 1000));
  return age >= 0 ? age : 0;
}

