from collections import deque

def maze_steps(grid):
    if not grid:
        raise ValueError("grid must be non-empty")

    row_len = len(grid[0])
    start = exit_ = None
    allowed = set("S E # .")
    for r, row in enumerate(grid):
        if len(row) != row_len:
            raise ValueError("rows must be the same length")
        for c, ch in enumerate(row):
            if ch not in allowed:
                raise ValueError("invalid character: %r" % ch)
            if ch == 'S':
                start = (r, c)
            elif ch == 'E':
                exit_ = (r, c)

    if start is None or exit_ is None:
        raise ValueError("grid must contain exactly one S and one E")

    rows, cols = len(grid), row_len

    def open_cell(r, c):
        return grid[r][c] != '#'

    def is_exit(r, c):
        return grid[r][c] == 'E'

    def is_wall(r, c):
        return grid[r][c] == '#'

    if start == exit_:
        return 0

    seen = {start}
    queue = deque([(start[0], start[1], 0)])
    while queue:
        r, c, d = queue.popleft()
        if (r, c) == exit_:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen:
                if open_cell(nr, nc) and not is_wall(nr, nc):
                    seen.add((nr, nc))
                    queue.append((nr, nc, d + 1))
    return -1
